// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this));
        address ownerBefore = c.owner();
        bool wasOwner = (actor == ownerBefore);
        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        // Rule: the call succeeds and owner becomes newOwner iff the caller was the owner;
        // otherwise it reverts and owner is unchanged.
        assertTrue(ok == wasOwner && c.owner() == (wasOwner ? newOwner : ownerBefore));
    }
}
